/* Palette: #1a1a2e (bg), #16213e (card), #0f3460 (accent), #e94560 (highlight), #f0f0f0 (text) */
* { margin: 0; padding: 0; box-sizing: border-box; }
[hidden] { display: none !important; }
body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: #1a1a2e;
  color: #f0f0f0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}
.card {
  background: #16213e;
  border-radius: 16px;
  padding: 32px 24px;
  width: 100%;
  max-width: 480px;
  box-shadow: 0 8px 32px rgba(0,0,0,0.4);
  display: flex;
  flex-direction: column;
  gap: 24px;
}
h1 {
  font-size: 1.5rem;
  text-align: center;
  color: #e94560;
  letter-spacing: 1px;
}
.settings {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 12px 16px;
  align-items: center;
}
.settings label {
  font-size: 1rem;
  color: #c0c0d0;
}
.settings input {
  width: 80px;
  padding: 8px;
  font-size: 1rem;
  border: 2px solid #0f3460;
  border-radius: 8px;
  background: #1a1a2e;
  color: #f0f0f0;
  text-align: center;
  transition: border-color 0.2s;
}
.settings input:focus {
  outline: none;
  border-color: #e94560;
}
.display {
  text-align: center;
  padding: 16px 0;
}
.phase {
  font-size: 1.5rem;
  font-weight: 700;
  color: #e94560;
  text-transform: uppercase;
  letter-spacing: 2px;
}
.round {
  font-size: 1rem;
  color: #a0a0b8;
  margin: 4px 0 8px;
}
.timer {
  font-size: 3.5rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: #f0f0f0;
  line-height: 1.1;
}
.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}
.btn {
  font-size: 1rem;
  font-weight: 600;
  padding: 12px 24px;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  background: #0f3460;
  color: #f0f0f0;
  transition: background 0.2s, transform 0.1s;
  flex: 1 1 auto;
  min-width: 100px;
}
.btn:hover:not(:disabled) {
  background: #1a4a7a;
}
.btn:focus-visible {
  outline: 3px solid #e94560;
  outline-offset: 2px;
}
.btn:active:not(:disabled) {
  transform: scale(0.96);
}
.btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}
.btn.primary {
  background: #e94560;
  color: #fff;
}
.btn.primary:hover:not(:disabled) {
  background: #f05a75;
}
.complete {
  text-align: center;
  font-size: 1.25rem;
  font-weight: 700;
  color: #e94560;
  padding: 8px;
  border: 2px solid #e94560;
  border-radius: 8px;
  animation: pulse 1s infinite alternate;
}
@keyframes pulse {
  from { opacity: 0.7; }
  to { opacity: 1; }
}
@media (max-width: 400px) {
  .card { padding: 24px 16px; }
  .timer { font-size: 2.8rem; }
  .btn { padding: 10px 16px; min-width: 80px; }
}

document.addEventListener('DOMContentLoaded', () => {
  const workInput = document.getElementById('work');
  const restInput = document.getElementById('rest');
  const roundsInput = document.getElementById('rounds');
  const phaseEl = document.getElementById('phase');
  const roundEl = document.getElementById('round');
  const timerEl = document.getElementById('timer');
  const startBtn = document.getElementById('start');
  const pauseBtn = document.getElementById('pause');
  const resetBtn = document.getElementById('reset');
  const completeEl = document.getElementById('complete');

  let timerId = null;
  let remaining = 0;
  let currentPhase = 'work';
  let currentRound = 1;
  let totalRounds = 3;
  let workSecs = 30;
  let restSecs = 15;
  let running = false;

  function formatTime(secs) {
    const m = Math.floor(secs / 60).toString().padStart(2, '0');
    const s = (secs % 60).toString().padStart(2, '0');
    return `${m}:${s}`;
  }

  function updateDisplay() {
    timerEl.textContent = formatTime(remaining);
    phaseEl.textContent = currentPhase === 'work' ? 'Work' : 'Rest';
    roundEl.textContent = `Round ${currentRound} / ${totalRounds}`;
  }

  function tick() {
    remaining--;
    if (remaining < 0) {
      if (currentPhase === 'work') {
        currentPhase = 'rest';
        remaining = restSecs;
      } else {
        currentRound++;
        if (currentRound > totalRounds) {
          finishWorkout();
          return;
        }
        currentPhase = 'work';
        remaining = workSecs;
      }
    }
    updateDisplay();
  }

  function finishWorkout() {
    clearInterval(timerId);
    timerId = null;
    running = false;
    phaseEl.textContent = 'Done';
    roundEl.textContent = `Completed ${totalRounds} rounds`;
    timerEl.textContent = '00:00';
    completeEl.hidden = false;
    startBtn.disabled = false;
    pauseBtn.disabled = true;
    workInput.disabled = false;
    restInput.disabled = false;
    roundsInput.disabled = false;
    try {
      const utterance = new SpeechSynthesisUtterance('Workout complete');
      speechSynthesis.speak(utterance);
    } catch (e) {
      // Speech not supported
    }
  }

  function start() {
    if (running) return;
    workSecs = Math.max(1, parseInt(workInput.value) || 30);
    restSecs = Math.max(1, parseInt(restInput.value) || 15);
    totalRounds = Math.max(1, parseInt(roundsInput.value) || 3);
    if (!timerId) {
      currentRound = 1;
      currentPhase = 'work';
      remaining = workSecs;
      completeEl.hidden = true;
    }
    running = true;
    startBtn.disabled = true;
    pauseBtn.disabled = false;
    workInput.disabled = true;
    restInput.disabled = true;
    roundsInput.disabled = true;
    updateDisplay();
    timerId = setInterval(tick, 1000);
  }

  function pause() {
    if (!running) return;
    clearInterval(timerId);
    timerId = null;
    running = false;
    startBtn.disabled = false;
    pauseBtn.disabled = true;
  }

  function reset() {
    clearInterval(timerId);
    timerId = null;
    running = false;
    currentPhase = 'work';
    currentRound = 1;
    workSecs = Math.max(1, parseInt(workInput.value) || 30);
    restSecs = Math.max(1, parseInt(restInput.value) || 15);
    totalRounds = Math.max(1, parseInt(roundsInput.value) || 3);
    remaining = workSecs;
    completeEl.hidden = true;
    phaseEl.textContent = 'Ready';
    roundEl.textContent = `Round 0 / ${totalRounds}`;
    timerEl.textContent = formatTime(remaining);
    startBtn.disabled = false;
    pauseBtn.disabled = true;
    workInput.disabled = false;
    restInput.disabled = false;
    roundsInput.disabled = false;
  }

  startBtn.addEventListener('click', start);
  pauseBtn.addEventListener('click', pause);
  resetBtn.addEventListener('click', reset);

  // Initialize display
  reset();
});
